const lockSubscriptionPoolShared = `-- name: LockSubscriptionPoolShared :one
SELECT id, name, runtime_type, description, spend_order, all_workspaces, revision, created_by, created_at, updated_at FROM subscription_pool WHERE id = $1 FOR SHARE
`

// A claim reads the pool and its members under a shared lock so a concurrent
// edit (which takes the exclusive lock) cannot slip between the two reads.
func (q *Queries) LockSubscriptionPoolShared(ctx context.Context, id pgtype.UUID) (SubscriptionPool, error) {
	row := q.db.QueryRow(ctx, lockSubscriptionPoolShared, id)
	var i SubscriptionPool
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.RuntimeType,
		&i.Description,
		&i.SpendOrder,
		&i.AllWorkspaces,
		&i.Revision,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

