const setPoolRuntimeProfilesEnabled = `-- name: SetPoolRuntimeProfilesEnabled :many
UPDATE runtime_profile rp
SET enabled = $1, updated_at = now()
WHERE rp.pool_id = $2
  AND rp.enabled <> $1
  AND ($1::bool = false OR rp.workspace_id IN (
        SELECT g.workspace_id FROM subscription_pool_grant g WHERE g.pool_id = $2
        UNION SELECT w.id FROM workspace w WHERE EXISTS (SELECT 1 FROM subscription_pool p WHERE p.id = $2 AND p.all_workspaces)))
RETURNING id, workspace_id, display_name, protocol_family, command_name, description, fixed_args, visibility, created_by, enabled, created_at, updated_at, runtime_type, pool_id
`

type SetPoolRuntimeProfilesEnabledParams struct {
	Enabled bool        `json:"enabled"`
	PoolID  pgtype.UUID `json:"pool_id"`
}

// Switching an environment of a pool on or off applies to the environments the
// pool is granted to; a revoked one stays off.
func (q *Queries) SetPoolRuntimeProfilesEnabled(ctx context.Context, arg SetPoolRuntimeProfilesEnabledParams) ([]RuntimeProfile, error) {
	rows, err := q.db.Query(ctx, setPoolRuntimeProfilesEnabled, arg.Enabled, arg.PoolID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RuntimeProfile{}
	for rows.Next() {
		var i RuntimeProfile
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.DisplayName,
			&i.ProtocolFamily,
			&i.CommandName,
			&i.Description,
			&i.FixedArgs,
			&i.Visibility,
			&i.CreatedBy,
			&i.Enabled,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RuntimeType,
			&i.PoolID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

