const updateSubscriptionPool = `-- name: UpdateSubscriptionPool :one
UPDATE subscription_pool
SET name = $1,
    description = $2,
    spend_order = $3,
    all_workspaces = $4,
    revision = revision + $5::int,
    updated_at = now()
WHERE id = $6
RETURNING id, name, runtime_type, description, spend_order, all_workspaces, revision, created_by, created_at, updated_at
`

type UpdateSubscriptionPoolParams struct {
	Name          string      `json:"name"`
	Description   string      `json:"description"`
	SpendOrder    string      `json:"spend_order"`
	AllWorkspaces bool        `json:"all_workspaces"`
	RevisionStep  int32       `json:"revision_step"`
	ID            pgtype.UUID `json:"id"`
}

// revision_step is 1 when the member set, their order or the spend order
// changes, 0 otherwise.
func (q *Queries) UpdateSubscriptionPool(ctx context.Context, arg UpdateSubscriptionPoolParams) (SubscriptionPool, error) {
	row := q.db.QueryRow(ctx, updateSubscriptionPool,
		arg.Name,
		arg.Description,
		arg.SpendOrder,
		arg.AllWorkspaces,
		arg.RevisionStep,
		arg.ID,
	)
	var i SubscriptionPool
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.RuntimeType,
		&i.Description,
		&i.SpendOrder,
		&i.AllWorkspaces,
		&i.Revision,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
